CREATE TABLE IF NOT EXISTS admins(id INTEGER PRIMARY KEY CHECK(id=1),username TEXT NOT NULL,pass_hash TEXT NOT NULL,created_at INTEGER);
CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY AUTOINCREMENT,tg_id INTEGER UNIQUE NOT NULL,username TEXT,first_name TEXT,chat_id INTEGER,phone TEXT,state TEXT,blocked INTEGER DEFAULT 0,vip INTEGER DEFAULT 0,vip_start INTEGER,vip_expiry INTEGER,bot_limit INTEGER DEFAULT 1,created_at INTEGER,last_active INTEGER);
CREATE TABLE IF NOT EXISTS sessions(id TEXT PRIMARY KEY,kind TEXT,ref INTEGER,csrf TEXT,expires INTEGER);
CREATE TABLE IF NOT EXISTS login_tokens(token TEXT PRIMARY KEY,user_id INTEGER,expires INTEGER);
CREATE TABLE IF NOT EXISTS bots(id INTEGER PRIMARY KEY AUTOINCREMENT,owner_id INTEGER,token TEXT,bot_tg_id INTEGER,name TEXT,username TEXT,secret TEXT,status INTEGER DEFAULT 1,webhook_ok INTEGER DEFAULT 0,group_chat_id INTEGER,group_title TEXT,created_at INTEGER);
CREATE TABLE IF NOT EXISTS bot_admins(id INTEGER PRIMARY KEY AUTOINCREMENT,bot_id INTEGER,tg_id INTEGER,username TEXT,perms TEXT DEFAULT 'commands,ai,moderation,autopost,settings');
CREATE TABLE IF NOT EXISTS settings(scope TEXT,k TEXT,v TEXT,PRIMARY KEY(scope,k));
CREATE TABLE IF NOT EXISTS commands(id INTEGER PRIMARY KEY AUTOINCREMENT,bot_id INTEGER,cmd TEXT,response TEXT,enabled INTEGER DEFAULT 1);
CREATE TABLE IF NOT EXISTS auto_replies(id INTEGER PRIMARY KEY AUTOINCREMENT,bot_id INTEGER,trig TEXT,mode TEXT,reply TEXT,enabled INTEGER DEFAULT 1);
CREATE TABLE IF NOT EXISTS bad_words(id INTEGER PRIMARY KEY AUTOINCREMENT,bot_id INTEGER,word TEXT);
CREATE TABLE IF NOT EXISTS warnings(bot_id INTEGER,tg_id INTEGER,count INTEGER DEFAULT 0,PRIMARY KEY(bot_id,tg_id));
CREATE TABLE IF NOT EXISTS cooldowns(bot_id INTEGER,tg_id INTEGER,chat_id INTEGER,till INTEGER,PRIMARY KEY(bot_id,tg_id));
CREATE TABLE IF NOT EXISTS scheduled_posts(id INTEGER PRIMARY KEY AUTOINCREMENT,bot_id INTEGER,text TEXT,next_run INTEGER,rep TEXT DEFAULT 'once',interval_min INTEGER DEFAULT 60,enabled INTEGER DEFAULT 1);
CREATE TABLE IF NOT EXISTS buttons(id INTEGER PRIMARY KEY AUTOINCREMENT,bot_id INTEGER,scope TEXT,label TEXT,url TEXT);
CREATE TABLE IF NOT EXISTS join_buttons(id INTEGER PRIMARY KEY AUTOINCREMENT,label TEXT,url TEXT,enabled INTEGER DEFAULT 1);
CREATE TABLE IF NOT EXISTS ai_providers(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT,kind TEXT,api_url TEXT,api_key TEXT,enabled INTEGER DEFAULT 1);
CREATE TABLE IF NOT EXISTS ai_models(id INTEGER PRIMARY KEY AUTOINCREMENT,provider_id INTEGER,model TEXT,priority INTEGER DEFAULT 10,free INTEGER DEFAULT 1,enabled INTEGER DEFAULT 1);
CREATE TABLE IF NOT EXISTS ai_usage(id INTEGER PRIMARY KEY AUTOINCREMENT,bot_id INTEGER,model TEXT,ok INTEGER,at INTEGER);
CREATE TABLE IF NOT EXISTS stats(bot_id INTEGER,k TEXT,n INTEGER DEFAULT 0,PRIMARY KEY(bot_id,k));
CREATE TABLE IF NOT EXISTS msglog(bot_id INTEGER,tg_id INTEGER,at INTEGER,h TEXT);
CREATE TABLE IF NOT EXISTS broadcasts(id INTEGER PRIMARY KEY AUTOINCREMENT,text TEXT,created_at INTEGER);
CREATE TABLE IF NOT EXISTS bq(id INTEGER PRIMARY KEY AUTOINCREMENT,bid INTEGER,chat_id INTEGER,st INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS logs(id INTEGER PRIMARY KEY AUTOINCREMENT,at INTEGER,kind TEXT,ref INTEGER,msg TEXT);
CREATE INDEX IF NOT EXISTS i_posts ON scheduled_posts(next_run);
CREATE INDEX IF NOT EXISTS i_msglog ON msglog(bot_id,at);
CREATE INDEX IF NOT EXISTS i_bq ON bq(st,id);
CREATE INDEX IF NOT EXISTS i_bots_owner ON bots(owner_id);
